public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns messages in a chat. The messages are returned in reverse chronological order (i.e., in order of decreasing message_id).
    /// For optimal performance, the number of returned messages is chosen by TDLib. This is an offline method if only_local is true
    /// </summary>
    public Task<TdLib.TdApi.Objects.Messages> GetChatHistoryAsync(long chatId = default, long fromMessageId = default, int offset = default, int limit = default, bool onlyLocal = default)
    {

           using var activity =  StartCallActivity("GetChatHistoryAsync", typeof(GetChatHistory).FullName ?? "GetChatHistoryAsync");

           try
           {
             return client.GetChatHistoryAsync(chatId, fromMessageId, offset, limit, onlyLocal);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
